class BinaryDataProcessor:
    ASCII_BYTE_LENGTH = 8
    BINARY_CHARS = '01'

    def __init__(self, binary_string):
        self._binary_string = binary_string
        self.clean_non_binary_chars()

    @property
    def binary_string(self):
        return self._binary_string

    @binary_string.setter
    def binary_string(self, value):
        self._binary_string = value

    def clean_non_binary_chars(self):
        self._binary_string = ''.join(filter(lambda x: x in self.BINARY_CHARS, self._binary_string))

    def _count_zeroes(self):
        return self._binary_string.count('0')

    def _count_ones(self):
        return self._binary_string.count('1')

    def _calculate_percentage(self, count):
        if self._binary_length() == 0:
            return 0.0
        return count / self._binary_length()

    def _binary_length(self):
        return len(self._binary_string)

    def calculate_binary_info(self):
        zeroes_count = self._count_zeroes()
        ones_count = self._count_ones()
        total_length = self._binary_length()

        zeroes_percentage = self._calculate_percentage(zeroes_count)
        ones_percentage = self._calculate_percentage(ones_count)

        return {
            'Zeroes': zeroes_percentage,
            'Ones': ones_percentage,
            'Bit length': total_length
        }

    def _convert_bytes(self, encoding='ascii'):
        byte_array = bytearray()
        for i in range(0, len(self._binary_string), self.ASCII_BYTE_LENGTH):
            byte = self._binary_string[i:i+self.ASCII_BYTE_LENGTH]
            if len(byte) < self.ASCII_BYTE_LENGTH:
                continue
            decimal = int(byte, 2)
            byte_array.append(decimal)
        return bytes(byte_array).decode(encoding)

    def convert_to_ascii(self):
        return self._convert_bytes('ascii')

    def convert_to_utf8(self):
        return self._convert_bytes('utf-8')
